def _cleanup():
    web.ctx.pop("_fieldstorage", None)
    web.ctx.pop("_data", None)
    web.ctx.env = {}


class upload:
    def POST(self, category):
        i = web.input(
            'olid',
            author=None,
            file={},
            source_url=None,
            success_url=None,
            failure_url=None,
        )

        success_url = i.success_url or web.ctx.get('HTTP_REFERRER') or '/'
        failure_url = i.failure_url or web.ctx.get('HTTP_REFERRER') or '/'

        def error(code__msg):
            (code, msg) = code__msg
            print("ERROR: upload failed, ", i.olid, code, repr(msg), file=web.debug)
            _cleanup()
            url = changequery(failure_url, errcode=code, errmsg=msg)
            raise web.seeother(url)

        if i.source_url:
            try:
                data = download(i.source_url)
# Keep in sync with web_nginx.conf
server {
    listen 80 default;
    listen [::]:443 ssl http2 ipv6only=on;
    listen 443 ssl http2;
    server_name localhost;

    ssl_certificate /etc/letsencrypt/live/covers.openlibrary.org/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/covers.openlibrary.org/privkey.pem;

    # Diffie-Hellman parameter for DHE ciphersuites, recommended 2048 bits
    ssl_dhparam /olsystem/etc/nginx/dhparam-2048.pem;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers EECDH+CHACHA20:EECDH+AES128:RSA+AES128:EECDH+AES256:RSA+AES256:EECDH+3DES:RSA+3DES:!MD5;
    ssl_prefer_server_ciphers on;

    # Needed for logging/IP anonymization
    include /olsystem/etc/nginx/logging_periodics.conf;
}

# Docker's internal load balancing ends up with unbalanced connections eventually.
# This must be kept in sync with the `replicas` value in `compose.production.yaml`
# for the `covers` service.
upstream covers_backend {
  least_conn;
  server openlibrary-covers-1:7075;
  server openlibrary-covers-2:7075;
}

server {
      listen 80;
      listen 443;
      server_name  covers.openlibrary.org;

      root /openlibrary;

      keepalive_timeout 5;

      # Return 429 errors as JSON.
      error_page 429 = @429;
      location @429 {
        default_type application/json;
        return 429 '{"status": 429, "message": "Too Many Requests. Please email us at info@archive.org"}';
      }

      location / {
        proxy_pass http://covers_backend;
        proxy_set_header Host $http_host;

        # Gunicorn takes IP from this header
        proxy_set_header X-Forwarded-For $remote_addr;

        # Hack to make the app pick the right url scheme even when the
        # app server is http only.
        proxy_set_header X-Scheme $scheme;

        if ($http_user_agent ~ (Bytespider) ) {
           return 444;
        }

        if ($http_user_agent ~ (CloudFront) ) {
           return 444;
        }


        # Covers rate limit.
        limit_req zone=cover_limit burst=400 nodelay;
        limit_req_status 429;
      }

      location ^~ /.well-known/acme-challenge/ {
        default_type "text/plain";
        root /openlibrary/static;
      }

      location ~ ^(/images/.*|favicon.ico|robots.txt)$ {
        rewrite ^(.*)$ /static/$1 last;
      }

      location ~ ^/(y_key_[0-9a-f]+.html|google[0-9a-f]+.html|LiveSearchSiteAuth.xml)$ {
        root /olsystem/www;
      }

      location /static {
        autoindex on;
        expires 1h;
      }

      location /static/build {
        expires max;
      }

      location /static/sitemaps {
        root /sitemaps;
      }
}
# Needed for IP anonymization
load_module modules/ngx_http_js_module.so;

user  www-data;

# XXX-Anand: Oct 2013
# Increased the worker_processes to allow more workers to share the load of https.

#worker_processes  1;
worker_processes 4;


error_log  /var/log/nginx/error.log;
pid        /var/run/nginx.pid;

events {
    worker_connections  2048;
    # multi_accept on;
}

http {
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache   shared:SSL:50m;
    ssl_session_timeout 10m;

    include       /etc/nginx/mime.types;

    server_names_hash_bucket_size   64;
    types_hash_bucket_size 64;

    # Logging / IP Anonymization; also need logging_periodics.conf inside a server block
    include /olsystem/etc/nginx/logging.conf;
    access_log    /var/log/nginx/access.log iacombined;

    client_max_body_size 50m;

    sendfile        on;
    #tcp_nopush     on;

    #keepalive_timeout  0;
    keepalive_timeout  65;
    tcp_nodelay        on;

    gzip  on;
    gzip_disable "MSIE [1-6]\.(?!.*SV1)";
    gzip_types       text/plain text/css application/x-javascript application/javascript application/xml;

    # Black-listed IPs
    include /olsystem/etc/nginx/deny.conf;

    # Rate limiting: https://nginx.org/en/docs/http/ngx_http_limit_req_module.html
    # No rate limit when IP obfuscation is not applied, as every IP is 255.0.0.0.
    # These rules only do anything if invoked, e.g., in web_nginx.conf.
    # TLDR: these rules can be disabled in `docker/web_nginx.conf`
    # and `docker/covers_nginx.conf`.
    geo $should_apply_limit {
      255.0.0.0 0;
      default 1;
    }

    map $should_apply_limit $rate_limit_key {
      0 '';
      1 $binary_remote_addr;
    }

    limit_req_zone $rate_limit_key zone=web_limit:10m rate=200r/m;
    # Set a more permissive limit for covers because some pages might load 20+ covers.
    limit_req_zone $rate_limit_key zone=cover_limit:10m rate=400r/m;

    # For returning 200 when someone tries to randomly sort author results.
    map $arg_sort $is_random_sort {
      default 0;
      ~^random_.* 1;
    }

    # Things are mounted into here by the docker compose file
    include /etc/nginx/sites-enabled/*;
}
